// Utility cost breakdown by state (approximate monthly splits)
export const getUtilitiesBreakdown = (st, total) => {
  const isHot  = ["TX","FL","AZ","LA","MS","AL","GA","SC","OK"].includes(st);
  const isCold = ["MN","WI","MI","IL","ND","SD","MT","WY","ME","VT","NH"].includes(st);
  const elecPct = isHot ? 0.55 : isCold ? 0.40 : 0.50;
  const gasPct  = isCold ? 0.30 : isHot ? 0.10 : 0.20;
  const waterPct = 0.20;
  const trashPct = 1 - elecPct - gasPct - waterPct;
  return [
    { label: "Electric" + (isHot ? " / A/C" : ""),           amount: Math.round(total * elecPct)  },
    { label: "Gas" + (isCold ? " / heating" : ""),           amount: Math.round(total * gasPct)   },
    { label: "Water & sewer",                                 amount: Math.round(total * waterPct) },
    { label: "Trash & other",                                 amount: Math.round(total * trashPct) },
  ];
};

